  const touching = code.split("\n").map((l) => l.trim()).filter((l) => names.test(l));
  for (const l of touching) if (!HARNESS_ALLOWED_LINES.some(([re]) => re.test(l))) v.push(`H1 a line names a profile value outside the enumerated forms: «${l}»`);
