    const flatStepM = steps === null ? (Math.max(0, kmh) / 3.6) * (dt / 1000) : steps[i];
    const r = wrongLegFlatStep(st, { now, t0, kmh, flatStepM, dtMs: dt, postedKmh: 50, follow: follow(i), probeAt: now });
    st = r.state;
