  const series = Array.from({ length: len }, () => (Rn() < 0.05 ? -1 : Math.round(rnd(0, 70))));
  const pauses = new Set(Array.from({ length: Math.floor(rnd(0, 4)) }, () => Math.floor(rnd(0, len))));
