  const dtMs = Math.round(rnd(300, 900));
  return { id, series, pauses, holdRest: (i) => i >= h0 && i < h1, follow: (i) => (lead[i] ? { present: true, parsed: true, meters: 40, heldSec: 2.6, needSec: 2, short: true, label: "x" } : null), dtMs };
